-- Check how many records have compliance issues (non-compliant in any area)
SELECT COUNT(*) as total FROM compliance;
SELECT COUNT(*) as non_compliant FROM compliance WHERE gdprcomp = 'Non-compliant' OR ccpacomp = 'Non-compliant' OR piplcomp = 'Non-compliant' OR loclawcomp = 'Non-compliant';

-- Check if recordregistry in auditandcompliance matches dataflow
SELECT COUNT(*) FROM auditandcompliance ac 
JOIN dataflow df ON ac.recordregistry = df.recordregistry;

-- Check compliance join
SELECT COUNT(*) FROM compliance c 
JOIN dataflow df ON c.recordregistry = df.recordregistry;

-- Check vendormanagement join
SELECT COUNT(*) FROM vendormanagement v 
JOIN dataflow df ON v.recordregistry = df.recordregistry;

-- Check if there are NULL recordregistry values in compliance or audit tables
SELECT COUNT(*) FROM compliance WHERE recordregistry IS NULL;
SELECT COUNT(*) FROM auditandcompliance WHERE recordregistry IS NULL;
SELECT COUNT(*) FROM vendormanagement WHERE recordregistry IS NULL;
